// One-shot: stamp `routing: { belongs, excludes }` onto every pack.mjs, right
// after its `id:` line. Scratchpad tooling — not part of the corpus.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const ROOT = '/home/user/Claudinite';
const routing = JSON.parse(readFileSync(process.argv[2], 'utf8'));

// The canon home's own local packs, authored here (they are not in the batch).
routing['local:canon-curation'] = {
  belongs:
    'the canon home maintaining itself — promoting member lessons into packs/, sweeping the fleet stack, policing the corpus tree',
  excludes: 'anything portable to a consuming repo — that belongs in a packs/ canon pack',
};
routing['local:claudinite'] = {
  belongs: 'working rules and lessons specific to developing Claudinite itself and not portable to any consumer',
  excludes: 'a lesson that travels to other repos — open it against packs/ instead',
};

const targets = {
  ...Object.fromEntries(Object.keys(routing).filter((k) => !k.startsWith('local:')).map((n) => [`packs/${n}/pack.mjs`, routing[n]])),
  '.claudinite/local/packs/canon-curation/pack.mjs': routing['local:canon-curation'],
  '.claudinite/local/packs/claudinite/pack.mjs': routing['local:claudinite'],
};

const esc = (s) => {
  if (s.includes("'")) throw new Error(`apostrophe in routing string: ${s}`);
  return s;
};

for (const [rel, r] of Object.entries(targets)) {
  const path = `${ROOT}/${rel}`;
  if (!existsSync(path)) throw new Error(`missing ${rel}`);
  const text = readFileSync(path, 'utf8');
  if (/\brouting:\s*\{/.test(text)) { console.log(`skip (has routing) ${rel}`); continue; }
  const m = /^(\s*)id:\s*['"][^'"]+['"],\s*$/m.exec(text);
  if (!m) throw new Error(`no id: line in ${rel}`);
  for (const k of ['belongs', 'excludes']) {
    const n = r[k].trim().split(/\s+/).length;
    if (n > 20) throw new Error(`${rel} ${k} is ${n} words`);
  }
  const indent = m[1];
  const block = `${indent}routing: {\n${indent}  belongs: '${esc(r.belongs)}',\n${indent}  excludes: '${esc(r.excludes)}',\n${indent}},\n`;
  const at = m.index + m[0].length + 1;
  writeFileSync(path, text.slice(0, at) + block + text.slice(at));
  console.log(`stamped ${rel}`);
}

