// One-shot migration: `rules:` -> `worldRules:` on every manifest, and a
// `skills:` declaration on every pack that bundles skills. The five packs with
// work-scoped rules are hand-edited afterwards. Scratchpad tooling.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = '/home/user/Claudinite';
const dirs = [
  ...readdirSync(join(ROOT, 'packs'), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => join(ROOT, 'packs', d.name)),
  ...readdirSync(join(ROOT, '.claudinite/local/packs'), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => join(ROOT, '.claudinite/local/packs', d.name)),
];

for (const dir of dirs) {
  const path = join(dir, 'pack.mjs');
  if (!existsSync(path)) continue;
  let text = readFileSync(path, 'utf8');
  const before = text;

  if (/^  rules: /m.test(text)) text = text.replace(/^  rules: /m, '  worldRules: ');

  const skillsRoot = join(dir, 'skills');
  const skills = existsSync(skillsRoot)
    ? readdirSync(skillsRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort()
    : [];
  if (skills.length && !/^  skills: /m.test(text)) {
    const decl = skills.length === 1
      ? `  skills: ['${skills[0]}'],\n`
      : `  skills: [\n${skills.map((s) => `    '${s}',`).join('\n')}\n  ],\n`;
    // Just before the closing brace of the default export.
    const at = text.lastIndexOf('\n};');
    text = `${text.slice(0, at + 1)}${decl}${text.slice(at + 1)}`;
  }

  if (text !== before) {
    writeFileSync(path, text);
    console.log(`migrated ${path.slice(ROOT.length + 1)}${skills.length ? ` (skills: ${skills.join(', ')})` : ''}`);
  }
}

