import sharedConstants from './shared-constants.mjs';
import catalogCompleteness from './catalog-completeness.mjs';
import claudiniteIsolation from './claudinite-isolation.mjs';
import schedulerWorkflowShape from './scheduler-workflow-shape.mjs';
import taskDeclarationShape from './task-declaration-shape.mjs';

// The baseline pack: working discipline, the task lifecycle, and the core
// checks. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly baselining
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
export default {
  id: 'basics',
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; GitHub Actions workflow or platform behaviour — github-actions; git procedure — git-github',
  },
  badge: 'badge.svg',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // The consumer-isolation wall rides the barriers mechanism: basics requires
  // the barriers pack and CONTRIBUTES the fixed barrier as manifest data
  // (claudinite-isolation.mjs — pure data, no cross-pack import;
  // pack-independence). git-github carries the git/GitHub side of the task
  // lifecycle (#385). Universal because basics is declared everywhere; the
  // requires closure materializes both declarations alongside it.
  requires: ['barriers', 'git-github'],
  contributes: { barriers: [claudiniteIsolation] },
  // Rules that audit the repo as it stands, whatever this session did.
  worldRules: [
    markdownLinkLabels,
    warningSuppression,
    filePlacement,
    claudeMdLength,
    generatedMergeDriver,
    sharedConstants,
    catalogCompleteness,
    // The per-project scheduling conformance guards (scheduled-tasks.md):
    // scheduling is baseline Claudinite discipline — the scheduler workflow and
    // the task-declaration contract are guarded wherever basics is declared
    // (everywhere). Both rules are relevance-first: inert until the repo carries
    // the workflow / a tasks/<name>/task.mjs of its own.
    schedulerWorkflowShape,
    taskDeclarationShape,
  ],
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation.
  workRules: [
    commentClassification,
    referenceIntegrity,
    taskLifecycle,
    squashMergeHistory,
  ],
  // The baseline skills — general engineering practice every project's work
  // can call for, whatever its technology — are bundled under skills/ in this
  // pack's own tree and mounted wherever basics is declared (which --init
  // seeds everywhere). The directory listing IS the manifest; when one stops
  // being a baseline activity, move its directory to the pack whose projects
  // need it (#385 moved the git/GitHub and Claudinite-lifecycle skills out).
  //
  // The baseline scheduled task every repo runs — baselining, the per-repo
  // self-refresh — lives in this pack's `tasks/baselining/`, discovered by the
  // scheduler's filesystem scan (engine/scheduler/discover.mjs), not declared
  // here. Being in basics — declared everywhere — makes it universal.
  skills: [
    'authoring-agent-docs',
    'bug-investigation',
    'bump-version',
    'engineering-practices',
    'file-placement',
    'repo-text-sweeps',
    'writing-tests',
  ],
};

#!/usr/bin/env node
// SessionStart hook: emit the prose of every declared pack (basics included)
// so the baseline and the project's technology guidance load once per session —
// the eager, reliable replacement for hoping a soft-pointer read fires. Its
// stdout becomes session context. Fails soft (emits nothing) on any error.
// Registered per-repo — see bootstrap.md.
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

try {
  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <canon>/engine/pack_loader
  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();

  let declared = [];
  const configPath = join(projectRoot, '.claudinite-checks.json');
  if (existsSync(configPath)) {
    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
    if (Array.isArray(raw.packs)) declared = raw.packs;
  }

  const { loadPacks, isActive } = await import(join(loaderDir, 'pack-registry.mjs'));
  // Include the project's own local packs (.claudinite/local_packs/) alongside
  // the canon: their prose loads the same way, so a project's rules ride the pack
  // system rather than an explicit @import.
  const packs = await loadPacks({ localRoot: projectRoot });

  const sections = [];
  for (const pack of packs) {
    if (!pack.prose || !isActive(pack, { packs: declared })) continue;
    // Resolve prose off the pack's OWN directory (canon or local_packs), not a
    // single shared root — so a local pack's RULES.md is found where it lives.
    const prosePath = join(pack.dir, pack.prose);
    if (!existsSync(prosePath)) continue;
    sections.push(`<!-- pack:${pack.id} -->\n${readFileSync(prosePath, 'utf8').trim()}`);
  }

  // The routing table: every pack's own statement of its boundary, so a session
  // holding a piece of content (a doc, a rule, a skill) routes it to the pack
  // that owns it instead of defaulting into the baseline. Emitted for every pack
  // DISCOVERED, not only the active ones — a consumer holds just the packs it
  // vendored, so the discovered set is already the set it can route into, and in
  // the canon every pack is a legitimate destination whether or not this repo
  // declares it. Rows are short by contract (the `pack-routing-declared` check
  // caps each side at 20 words), so the whole table stays a cheap session cost.
  const routed = packs.filter((p) => p.ruleRoutingGuidance?.belongs && p.ruleRoutingGuidance?.excludes);
  const routingTable = routed.length
    ? `# Claudinite — where content goes (pack routing)\n\nEach pack states what it owns and what it does not. When a rule, doc, skill or check could live in more than one, this table decides it — and "no pack fits" means a new pack or the project's own \`local_packs/\`, never the baseline by default.\n\n| Pack | Belongs | Does not belong |\n|---|---|---|\n${routed
        .map((p) => `| \`${p.id}\`${p.local ? ' (local)' : ''} | ${p.ruleRoutingGuidance.belongs} | ${p.ruleRoutingGuidance.excludes} |`)
        .join('\n')}\n`
    : '';

  if (sections.length || routingTable) {
    const guidance = sections.length
      ? `# Claudinite — active-pack guidance\n\nThe baseline plus the packs this project declares. Deeper per-pack reference (e.g. a pack's release doc) is linked from its prose and read on demand.\n\n${sections.join('\n\n---\n\n')}\n`
      : '';
    process.stdout.write([guidance, routingTable].filter(Boolean).join('\n---\n\n'));
  }
} catch {
  // fail soft — a broken loader must never block a session
}

