// Strip the sections a pack README no longer owns — the checks table and the
// skills table, both now declared on pack.mjs. Prints what survives so each
// file's fate is a judgement call, not a guess. Scratchpad tooling.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = '/home/user/Claudinite';
const DROP = /^##+ (Checks|Skills)\b/i;

for (const name of readdirSync(join(ROOT, 'packs'), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name)) {
  const path = join(ROOT, 'packs', name, 'README.md');
  if (!existsSync(path)) continue;
  const lines = readFileSync(path, 'utf8').split('\n');
  const kept = [];
  let dropping = false;
  for (const line of lines) {
    if (/^##+ /.test(line)) dropping = DROP.test(line);
    if (!dropping) kept.push(line);
  }
  const out = `${kept.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd()}\n`;
  const body = out.split('\n').slice(1).join('\n').trim();
  writeFileSync(path, out);
  console.log(`--- ${name} (${body.split('\n').filter(Boolean).length} content lines)`);
  console.log(body.split('\n').slice(0, 3).join('\n'));
}

