import { readdirSync, readFileSync, existsSync } from 'node:fs';
const dirs=[...readdirSync('packs',{withFileTypes:true}).filter(d=>d.isDirectory()).map(d=>'packs/'+d.name),
            ...readdirSync('.claudinite/local/packs',{withFileTypes:true}).filter(d=>d.isDirectory()).map(d=>'.claudinite/local/packs/'+d.name)];
let stats={detect:0,detectSimple:0,env:0,contributes:0,contributedRules:0,questions:0,imports:0,commentLines:0,totalLines:0,packs:0};
for(const d of dirs){const p=d+'/pack.mjs'; if(!existsSync(p))continue; const t=readFileSync(p,'utf8'); stats.packs++;
  const lines=t.split('\n'); stats.totalLines+=lines.length;
  stats.commentLines+=lines.filter(l=>/^\s*\/\//.test(l)).length;
  if(/detect:\s*\(/.test(t))stats.detect++;
  if(/detect:\s*\(ctx\)\s*=>\s*ctx\.tracked\.some\(\(f\)\s*=>\s*(f\.endsWith|\/\^)/.test(t))stats.detectSimple++;
  if(/^\s*env:/m.test(t))stats.env++;
  if(/^\s*contributes:/m.test(t))stats.contributes++;
  if(/^\s*contributedRules/m.test(t))stats.contributedRules++;
  if(/^\s*questions:/m.test(t))stats.questions++;
  stats.imports+=(t.match(/^import /gm)||[]).length;
}
console.log(stats);
"

