46	export function packQuestions(pack) {
47	  const questions = [];
48	  const errors = [];
49	  const src = pack.questions;
50	  if (src === undefined || src === null) return { questions, errors };
51	  if (!Array.isArray(src)) {
52	    errors.push({
53	      what: `the "${pack.id}" pack declares a non-array "questions"`,
54	      fix: 'make questions an array of { id, prompt } entries',
55	    });
56	    return { questions, errors };
57	  }
58	  const seen = new Set();
59	  for (const q of src) {
60	    if (q === null || typeof q !== 'object' || typeof q.id !== 'string' || !q.id
61	      || typeof q.prompt !== 'string' || !q.prompt) {
62	      errors.push({
63	        what: `the "${pack.id}" pack declares a malformed question ${JSON.stringify(q)}`,
64	        fix: 'give each question a non-empty string "id" and "prompt"',
65	      });
66	      continue;
67	    }
68	    if (seen.has(q.id)) {
69	      errors.push({
70	        what: `the "${pack.id}" pack declares question id "${q.id}" twice`,
71	        fix: 'question ids must be unique within the pack — rename one',
72	      });
73	      continue;
74	    }
75	    seen.add(q.id);
76	    questions.push(q);
77	  }
78	  return { questions, errors };
